schema:
{
  "contact": {
    "fullName": "string (required)",
    "headline": "string (optional, e.g. 'Senior AI Engineer')",
    "email": "string (optional, valid email)",
    "phone": "string (optional)",
    "location": "string (optional, e.g. 'Austin, TX')",
    "linkedin": "string (optional)",
    "website": "string (optional)"
  },
  "summary": ["string (required, 1-12 entries, each a complete sentence or clause)"],
  "skills": [
    { "category": "string (required)", "items": ["string (required, 1-40 entries)"] }
  ],
  "experience": [
    {
      "company": "string (required)",
      "location": "string (optional)",
      "role": "string (required)",
      "startDate": "string (required, e.g. 'Jan 2021')",
      "endDate": "string (required, e.g. 'Present')",
      "project": "string (optional)",
      "bullets": ["string (required, 1-20 entries)"]
    }
  ],
  "education": [
    {
      "institution": "string (required)",
      "degree": "string (required)",
      "field": "string (optional)",
      "location": "string (optional)",
      "startDate": "string (optional)",
      "endDate": "string (optional)"
    }
  ],
  "projects": [
    {
      "name": "string (required)",
      "description": "string (optional)",
      "technologies": ["string (optional)"],
      "bullets": ["string (optional)"]
    }
  ],
  "coverLetter": {
    "greeting": "string (optional)",
    "paragraphs": ["string (required when coverLetter is present)"],
    "closing": "string (optional)"
  }
}
